#!/usr/bin/env bash
#
# A wizard walks a human through setting up and validating Visual Studio Marketplace
# (VS Code) and Open VSX Registry (Cursor) publishing credentials for GitPR.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

PUBLISHER_ID="natanfiuza"
TOTAL_STAGES=5

banner "GitPR Extension Marketplace Setup Wizard"

# ── Stage 1: Prerequisites Check ──────────────────────────────────────────
stage "Check Local Prerequisites"
say "Verifying local environment tools required for credential verification and setup."

if command -v gh >/dev/null 2>&1; then
  if gh auth status >/dev/null 2>&1; then
    printf '  %s✓%s GitHub CLI (gh) is authenticated\n' "$GREEN" "$RESET"
  else
    warn "gh is installed but not authenticated. Run 'gh auth login' or secrets will be configured manually."
  fi
else
  warn "gh is not installed. You will be prompted with links to set secrets manually via GitHub Web UI."
fi

if command -v npx >/dev/null 2>&1; then
  printf '  %s✓%s npx is available for token verification\n' "$GREEN" "$RESET"
else
  warn "npx is not installed. Automated token verification will be skipped."
fi

pause "Press Enter to proceed to Visual Studio Marketplace setup"

# ── Stage 2: Visual Studio Marketplace (Azure DevOps PAT) ─────────────────
stage "Visual Studio Marketplace (Azure DevOps PAT)"
say "The Visual Studio Marketplace requires an Azure DevOps Personal Access Token (PAT)."
step "1. Ensure you have an Azure DevOps Organization (e.g. at https://dev.azure.com)."
step "2. Ensure Publisher ID '${PUBLISHER_ID}' is registered at https://marketplace.visualstudio.com/manage"
open_url "https://marketplace.visualstudio.com/manage"
pause "Verify or create publisher ID '${PUBLISHER_ID}', then press Enter"

say "Opening Azure DevOps Personal Access Tokens page..."
open_url "https://dev.azure.com"
step "3. Click User Settings (gear icon, top-right) → Personal access tokens → + New Token"
step "4. Name: gitpr-marketplace-publish"
step "5. Organization: Select 'All accessible organizations' (CRITICAL: vsce requires multi-org)"
step "6. Scopes: Show all scopes → Marketplace → check 'Acquire' and 'Manage'"
step "7. Click Create and copy the generated PAT token"

ask_secret VSCE_PAT "Paste your Visual Studio Marketplace PAT (VSCE_PAT):"

# ── Stage 3: Validate and Provision VSCE_PAT ──────────────────────────────
stage "Validate & Provision VSCE_PAT"
say "Testing VSCE_PAT validity with Visual Studio Marketplace API..."

VSCE_VERIFIED=false
if command -v npx >/dev/null 2>&1 && [[ -n "${VSCE_PAT:-}" ]]; then
  if npx --yes @vscode/vsce verify-pat "$PUBLISHER_ID" -p "$VSCE_PAT" >/dev/null 2>&1; then
    printf '  %s✓%s VSCE_PAT verified successfully for publisher %s\n' "$GREEN" "$RESET" "$PUBLISHER_ID"
    VSCE_VERIFIED=true
  else
    warn "Automated verification returned a non-zero exit code."
    note "Common causes: Token missing 'All accessible organizations' or publisher '$PUBLISHER_ID' not yet created."
    if ! confirm "Proceed with setting VSCE_PAT anyway?"; then
      warn "Aborted setting VSCE_PAT. You can re-run the wizard later."
      VSCE_PAT=""
    fi
  fi
else
  note "Automated verification skipped (npx missing or token empty)."
fi

if [[ -n "${VSCE_PAT:-}" ]]; then
  set_secret "VSCE_PAT" "$VSCE_PAT"
fi

pause "Press Enter to proceed to Open VSX Registry setup"

# ── Stage 4: Open VSX Registry (Cursor & Open IDEs) ───────────────────────
stage "Open VSX Registry Setup"
say "Open VSX Registry powers extension search in Cursor, VSCodium, and Gitpod."
open_url "https://open-vsx.org"
step "1. Sign in to open-vsx.org using your GitHub account (${PUBLISHER_ID})."
step "2. Register or verify namespace '${PUBLISHER_ID}' at https://open-vsx.org/user-settings/namespaces"
open_url "https://open-vsx.org/user-settings/namespaces"
pause "Verify namespace '${PUBLISHER_ID}', then press Enter"

say "Generating Open VSX Access Token..."
open_url "https://open-vsx.org/user-settings/tokens"
step "3. Go to User Settings → Access Tokens and create a new token (e.g. 'gitpr-ovsx-token')."
step "4. Copy the generated token string."

ask_secret OVSX_PAT "Paste your Open VSX Access Token (OVSX_PAT):"

# ── Stage 5: Validate, Provision OVSX_PAT & Release Prompt ────────────────
stage "Validate OVSX_PAT & Finalize Setup"
say "Testing OVSX_PAT validity with Open VSX Registry API..."

OVSX_VERIFIED=false
if command -v npx >/dev/null 2>&1 && [[ -n "${OVSX_PAT:-}" ]]; then
  if npx --yes ovsx verify-pat -p "$OVSX_PAT" >/dev/null 2>&1; then
    printf '  %s✓%s OVSX_PAT verified successfully\n' "$GREEN" "$RESET"
    OVSX_VERIFIED=true
  else
    warn "Automated verification returned a non-zero exit code."
    note "Common causes: Invalid token or account not associated with namespace '$PUBLISHER_ID'."
    if ! confirm "Proceed with setting OVSX_PAT anyway?"; then
      warn "Aborted setting OVSX_PAT. You can re-run the wizard later."
      OVSX_PAT=""
    fi
  fi
else
  note "Automated verification skipped (npx missing or token empty)."
fi

if [[ -n "${OVSX_PAT:-}" ]]; then
  set_secret "OVSX_PAT" "$OVSX_PAT"
fi

printf '\n'
say "Marketplace credential configuration completed!"
if confirm "Would you like to create and push release tag 'ext-v0.1.0' now?"; then
  say "Creating annotated tag ext-v0.1.0..."
  git tag -a "ext-v0.1.0" -m "release: GitPR Editor Extension v0.1.0"
  say "Pushing tag ext-v0.1.0 to origin..."
  git push origin "ext-v0.1.0"
  printf '  %s✓%s Release tag pushed! GitHub Actions will package and publish the extension.\n' "$GREEN" "$RESET"
else
  note "Tag creation skipped. You can trigger the release manually anytime with:"
  note "  git tag -a ext-v0.1.0 -m 'release: GitPR Editor Extension v0.1.0'"
  note "  git push origin ext-v0.1.0"
fi

finish
